/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT s.id, h.fee_cents
FROM subscription AS s
JOIN LATERAL (
  SELECT fee_cents
  FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC
  LIMIT 1
) AS h ON true
ON CONFLICT (subscription_id) DO NOTHING;

DO "'$$
DECLARE
  invalid_count bigint;
  invalid_subscriptions text;
BEGIN
  SELECT count(*), string_agg(subscription_id, '"', ' ORDER BY subscription_id)
    INTO invalid_count, invalid_subscriptions
    FROM pricing_decision WHERE fee_cents < 0;
  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'Cannot add fee_non_negative: % invalid pricing decision(s), subscriptions: %',
      invalid_count, invalid_subscriptions USING ERRCODE = 'P0001';
  END IF;
END "'$$;

ALTER TABLE pricing_decision ADD CONSTRAINT fee_non_negative CHECK (fee_cents >= 0);
COMMIT;
EOF
cat > subscriptions.ts <<'"'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? subscription.terms?.monthlyFeeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents, ...terms } = previous.terms;
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  return getFee(subscription) "'!== subscription.terms.monthlyFeeCents;
}

export function acceptLegacyTerms(input: any) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('"'invalid');
  return input;
}
EOF
cat > smoke.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { acceptLegacyTerms, changedSinceApproval, getFee, MIN_FEE, newVersion } from './subscriptions';

test('uses approved decision, including zero, and reads legacy fees', () => {
  expect(getFee({ terms: { monthlyFeeCents: 900 }, pricingDecision: { feeCents: 2500 } })).toBe(2500);
  expect(getFee({ terms: { monthlyFeeCents: 900 }, pricingDecision: { feeCents: 0 } })).toBe(0);
  expect(getFee({ terms: { monthlyFeeCents: 900 } })).toBe(900);
  expect(getFee({ terms: {} })).toBe(MIN_FEE);
});

test('new versions require a new fee decision', () => {
  const previous = { terms: { monthlyFeeCents: 900, name: 'standard' }, pricingDecision: { feeCents: 1000 } };
  expect(newVersion(previous)).toEqual({ terms: { name: 'standard' } });
  expect(previous.terms.monthlyFeeCents).toBe(900);
});

test('compares approved and current fee and accepts legacy integers', () => {
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 900 }, pricingDecision: { feeCents: 1000 } })).toBe(true);
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 900 } })).toBe(false);
  expect(acceptLegacyTerms({ monthlyFeeCents: -1 }).monthlyFeeCents).toBe(-1);
});
EOF
bun test"

